    /**
     * Tests getting all PaymentContracts.
     *
     * @return    Collection
     */
    public List<PaymentContract> testGetAll() throws Throwable {
    LOGGER.info( "PaymentContractTest:testGetAll() - Retrieving Collection of PaymentContracts:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all PaymentContract : " );
    List<PaymentContract> collection  = null;

    try {
        // call the static get method on the PaymentContractService
        collection = service.getAllPaymentContract();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            PaymentContract currEntity  = null;
            Iterator<PaymentContract> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getPaymentContractId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

